return from(this.callOpenAI(prompt));
}
private async callOpenAI(prompt: string): Promise {
const response = await this.openai.createCompletion({
model: 'text-davinci-003',
prompt,
max_tokens: 150,
temperature: 0.7
});
return response.data.choices[0].text.trim();
}
}
